# Сценарии партии FINAL_v8 — 3 ролика (решение Игоря 14.10: качество вместо количества).
# Озвучки нет: история — крупными пословными репликами на экране (~2,5 слова/с), *слово* = цветной акцент + punch-in зум визуала.
# s — реплика, fwd=1 — строка репоста (янтарная рамка). vis — визуал сцены.
# Сцена 0 — хук (крупный текст с первого кадра + движение fx); последняя — тот же хук (закольцовка) + «Подпишись — …» в последние 3 с.
# Слоты публикатора: order 1 → 12:00 (пробный, блок B), order 2 → 16:00 (пробный, блок D), order 3 → 20:00 (обычный, ГЛАВНЫЙ — шаг курса, блок A).
# ПРАВИЛО ХУКА: первая фраза — сбой/секрет, который зритель видел в своём чате, + обещание ответа; без формул, списков и терминов.

def L(s, **k):
    return dict(s=s, **k)

def SAVE(title, txt):
    return {'t': 'save', 'title': title, 'text': txt}

def SHARE(to):
    return dict(vis={'t': 'share', 'to': to}, lines=[L('Отправьте ' + to.replace(' ', ' *', 1) + '*.', fwd=1)])

